def _dense_dms_steady_ssa(document, function_name):
    """Alpha-rename only dms_steady after CFG compaction; preserve every operation."""
    import copy
    assert document["schema"] == "hepta.hia.program.v8"
    assert document["module"] == "agent_namespace_dms_map_join_r10"
    indices = [i for i, fn in enumerate(document["functions"]) if fn["name"] == function_name]
    assert len(indices) == 1
    index = indices[0]
    original = document["functions"][index]
    assert set(original) == {"name", "params", "returns", "effects", "entry", "blocks"}
    entries = [block for block in original["blocks"] if block["id"] == original["entry"]]
    assert len(entries) == 1 and original["params"] == entries[0]["params"]
    definitions = {}
    for block in original["blocks"]:
        assert set(block) == {"id", "params", "ops", "term"}
        values = list(block["params"])
        for op in block["ops"]:
            assert set(op) == {"op", "args", "out", "attrs"}
            values.extend(op["out"])
        for value in values:
            assert set(value) == {"name", "type"}
            name = value["name"]
            assert type(name) is str and name.startswith("v") and name[1:]
            assert name[1:].isascii() and name[1:].isdigit()
            assert name == "v" + str(int(name[1:])) and name not in definitions
            definitions[name] = value["type"]
    ordered = sorted(definitions, key=lambda name: int(name[1:]))
    mapping = {name: "v" + str(i) for i, name in enumerate(ordered)}
    inverse = {new: old for old, new in mapping.items()}
    assert len(mapping) == len(inverse) == len(definitions)
    assert all(int(name[1:]) < 2048 for name in inverse)

    def renamed(fn, table):
        fn = copy.deepcopy(fn)
        def refs(values):
            assert type(values) is list and all(type(x) is str and x in table for x in values)
            return [table[x] for x in values]
        def params(values):
            for value in values:
                value["name"] = table[value["name"]]
        params(fn["params"])
        for block in fn["blocks"]:
            params(block["params"])
            for op in block["ops"]:
                op["args"] = refs(op["args"])
                params(op["out"])
            term = block["term"]
            if term["op"] == "ret":
                assert set(term) == {"op", "values"}
                term["values"] = refs(term["values"])
            elif term["op"] == "jump":
                assert set(term) == {"op", "target", "args"}
                term["args"] = refs(term["args"])
            elif term["op"] == "branch":
                assert set(term) == {"op", "cond", "then", "else"}
                term["cond"] = table[term["cond"]]
                for edge_name in ("then", "else"):
                    edge = term[edge_name]
                    assert set(edge) == {"target", "args"}
                    edge["args"] = refs(edge["args"])
            else:
                raise ValueError("unexpected dms_steady terminator")
        return fn

    rewritten = renamed(original, mapping)
    assert renamed(rewritten, inverse) == original
    result = copy.deepcopy(document)
    result["functions"][index] = rewritten
    return result

